/* AS_IS Rexpert Preview 주석 처리 */
scwin.fn_Print = function() {
    scwin.fn_getTitle('R');

    //2.총계
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var g_MKT_ID = $c.stf.getObjectValue(rdo_MKT_ID);
        if (g_MKT_ID == '1') {
            //fn_totalPrint_S( dts_2_1A, dts_2_1C, dts_2_2A, dts_2_3A, dts_2_1D);
            scwin.fn_totalPrint_S_pdf(dts_2_1A, dts_2_1C, dts_2_2A, dts_2_3A, dts_2_1D);
        } else if (g_MKT_ID == '2') {
            //fn_totalPrint_K( dts_2_1A, dts_2_1B, dts_2_1C, dts_2_2A, dts_2_2B, dts_2_3A, dts_2_3B, dts_2_1D);
            scwin.fn_totalPrint_K_pdf(dts_2_1A, dts_2_1B, dts_2_1C, dts_2_2A, dts_2_2B, dts_2_3A, dts_2_3B, dts_2_1D);
        }
    }
    //3.업종
    else if (MaxTab_01.getSelectedTabIndex() == 2) {
        //fn_idxIndPrint( dts_3_1A, dts_3_2A, dts_3_3A);
        scwin.fn_idxIndPrint_pdf(dts_3_1A, dts_3_2A, dts_3_3A);
    }
    //4.매출액
    else if (MaxTab_01.getSelectedTabIndex() == 3) {
        //fn_rankPrint( dts_4_1A, dts_4_1B, dts_4_1C, dts_4_1D, dts_4_2A, dts_4_2B, dts_4_2C, dts_4_2D, dts_4_3A, dts_4_3B, dts_4_3C, dts_4_3D);
        scwin.fn_rankPrint_pdf(dts_4_1A, dts_4_1B, dts_4_1C, dts_4_1D, dts_4_2A, dts_4_2B, dts_4_2C, dts_4_2D, dts_4_3A, dts_4_3B, dts_4_3C, dts_4_3D);
    }
    //5.영업이익
    else if (MaxTab_01.getSelectedTabIndex() == 4) {
        //fn_rankPrint( dts_5_1A, dts_5_1B, dts_5_1C, dts_5_1D, dts_5_2A, dts_5_2B, dts_5_2C, dts_5_2D, dts_5_3A, dts_5_3B, dts_5_3C, dts_5_3D);
        scwin.fn_rankPrint_pdf(dts_5_1A, dts_5_1B, dts_5_1C, dts_5_1D, dts_5_2A, dts_5_2B, dts_5_2C, dts_5_2D, dts_5_3A, dts_5_3B, dts_5_3C, dts_5_3D);
    }
    //6.법인세차감전이익
    else if (MaxTab_01.getSelectedTabIndex() == 5) {
        //fn_rankPrint( dts_6_1A, dts_6_1B, dts_6_1C, dts_6_1D, dts_6_2A, dts_6_2B, dts_6_2C, dts_6_2D, dts_6_3A, dts_6_3B, dts_6_3C, dts_6_3D);
        scwin.fn_rankPrint_pdf(dts_6_1A, dts_6_1B, dts_6_1C, dts_6_1D, dts_6_2A, dts_6_2B, dts_6_2C, dts_6_2D, dts_6_3A, dts_6_3B, dts_6_3C, dts_6_3D);
    }
    //7.순이익
    else if (MaxTab_01.getSelectedTabIndex() == 6) {
        //fn_rankPrint( dts_7_1A, dts_7_1B, dts_7_1C, dts_7_1D, dts_7_2A, dts_7_2B, dts_7_2C, dts_7_2D, dts_7_3A, dts_7_3B, dts_7_3C, dts_7_3D);
        scwin.fn_rankPrint_pdf(dts_7_1A, dts_7_1B, dts_7_1C, dts_7_1D, dts_7_2A, dts_7_2B, dts_7_2C, dts_7_2D, dts_7_3A, dts_7_3B, dts_7_3C, dts_7_3D);
    }
    //7-1.지배기업순이익
    else if (MaxTab_01.getSelectedTabIndex() == 7) {
        //fn_rankPrint( dts_8_1A, dts_8_1B, dts_8_1C, dts_8_1D, dts_8_2A, dts_8_2B, dts_8_2C, dts_8_2D, dts_8_3A, dts_8_3B, dts_8_3C, dts_8_3D);
        scwin.fn_rankPrint_pdf(dts_8_1A, dts_8_1B, dts_8_1C, dts_8_1D, dts_8_2A, dts_8_2B, dts_8_2C, dts_8_2D, dts_8_3A, dts_8_3B, dts_8_3C, dts_8_3D);
    }
    //8.매출액영업이익률
    else if (MaxTab_01.getSelectedTabIndex() == 8) {
        //fn_saleProfPrint( dts_10_1A, dts_10_2A, dts_10_3A);
        scwin.fn_saleProfPrint_pdf(dts_10_1A, dts_10_2A, dts_10_3A);
    }
    //9.부채비율
    else if (MaxTab_01.getSelectedTabIndex() == 9) {
        //fn_deptRtoPrint(dts_11_1A, dts_11_1B);
        scwin.fn_deptRtoPrint_pdf(dts_11_1A, dts_11_1B);
    }
    //10.흑적자전환
    else if (MaxTab_01.getSelectedTabIndex() == 10) {
        //fn_plusMinusRankPrint(dts_12_1A, dts_12_1C, dts_12_2A, dts_12_2C, dts_12_3A, dts_12_3C);
        scwin.fn_plusMinusRankPrint_pdf(dts_12_1A, dts_12_1C, dts_12_2A, dts_12_2C, dts_12_3A, dts_12_3C);
    }
    //11.회사별실적_완료
    else if (MaxTab_01.getSelectedTabIndex() == 11) {
        //fn_byCorpPrfmPrint(dts_13_1A, dts_13_2A);
        scwin.fn_byCorpPrfmPrint_pdf(dts_13_1A, dts_13_2A);
    }
    //12.별도산출물(코)
    else if (MaxTab_01.getSelectedTabIndex() == 12) {
        //fn_kosdaqOthePrint(dts_14_1A, dts_14_1B, dts_14_1C, dts_14_1D, dts_14_1E);
        scwin.fn_kosdaqOthePrint_pdf(dts_14_1A, dts_14_1B, dts_14_1C, dts_14_1D, dts_14_1E);
    }
};
scwin.fn_getCurYear = function(pD) {
    var gYear = $c.stf.getObjectValue(cmb_ACNTCLS_YY);
    if (pD == 0) {
        gYear = gYear;
    } else if (pD == 1) {
        gYear = gYear + '년';
    } else if (pD == 2) {
        //gYear = "'"+gYear.substring(2, 4);
        gYear = gYear + '년';
    }
    return gYear;
};
scwin.fn_getPreYear = function(pD) {
    var gYear = $c.stf.getObjectValue(cmb_ACNTCLS_YY) - 1;
    if (pD == 0) {
        gYear = gYear;
    } else if (pD == 1) {
        gYear = gYear + '년';
    } else if (pD == 2) {
        //gYear = "'"+String(gYear).substring(2, 4);
        gYear = gYear + '년';
    }
    return gYear;
};
scwin.arrPar = new Array();
scwin.fn_getTitle = function(pType) {
    var sQTR_1 = '';
    var sQTR_2 = '';
    var sQTR_3 = '';
    var sFSTTRM_1 = '';
    var sCURTRM_1 = '';
    var sFSTTRM_2 = '';
    var sCURTRM_2 = '';
    var sFSTTRM_3 = '';
    var sCURTRM_3 = '';
    var sFSTTRM = scwin.fn_getPreYear(1) + " 12월말";
    var sCURTRM = '';
    var vNewLine = '';
    if (pType == 'G') {
        //grid header
        vNewLine = ';';
    } else if (pType == 'R') {
        //report header
        vNewLine = '\n';
    }
    if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '3') {
        //3 = 1분기
        sCURTRM = scwin.fn_getCurYear(1) + " 3월말";
        sFSTTRM_1 = scwin.fn_getPreYear(1) + vNewLine + "1분기";
        sCURTRM_1 = scwin.fn_getCurYear(1) + vNewLine + "1분기";
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '5') {
        //5 = 반기
        sQTR_1 = "□ 전년 동기 대비 상반기 실적(1~6월)";
        sQTR_2 = "□ " + scwin.fn_getCurYear(2) + " 1분기 대비 " + scwin.fn_getCurYear(2) + " 2분기 실적(4~6월)";
        sQTR_3 = "□ " + scwin.fn_getPreYear(2) + " 2분기 대비 " + scwin.fn_getCurYear(2) + " 2분기 실적(4~6월)";
        sCURTRM = scwin.fn_getCurYear(1) + " 6월말";
        sFSTTRM_1 = scwin.fn_getPreYear(1) + vNewLine + "상반기";
        sCURTRM_1 = scwin.fn_getCurYear(1) + vNewLine + "상반기";
        sFSTTRM_2 = scwin.fn_getCurYear(1) + vNewLine + "1분기";
        sCURTRM_2 = scwin.fn_getCurYear(1) + vNewLine + "2분기";
        sFSTTRM_3 = scwin.fn_getPreYear(1) + vNewLine + "2분기";
        sCURTRM_3 = scwin.fn_getCurYear(1) + vNewLine + "2분기";
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '6') {
        // 6 = 3분기
        sQTR_1 = "□ 전년 동기 대비 3분기 누적 실적(1~9월)";
        sQTR_2 = "□ " + scwin.fn_getCurYear(2) + " 2분기 대비 " + scwin.fn_getCurYear(2) + " 3분기 실적(7~9월)";
        sQTR_3 = "□ " + scwin.fn_getPreYear(2) + " 3분기 대비 " + scwin.fn_getCurYear(2) + " 3분기 실적(7~9월)";
        sCURTRM = scwin.fn_getCurYear(1) + " 9월말";
        sFSTTRM_1 = scwin.fn_getPreYear(1) + vNewLine + "1~9월";
        sCURTRM_1 = scwin.fn_getCurYear(1) + vNewLine + "1~9월";
        sFSTTRM_2 = scwin.fn_getCurYear(1) + vNewLine + "2분기";
        sCURTRM_2 = scwin.fn_getCurYear(1) + vNewLine + "3분기";
        sFSTTRM_3 = scwin.fn_getPreYear(1) + vNewLine + "3분기";
        sCURTRM_3 = scwin.fn_getCurYear(1) + vNewLine + "3분기";
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '1') {
        // 1 = 결산
        sQTR_1 = "";
        sCURTRM = scwin.fn_getCurYear(1) + " 12월말";
        sFSTTRM_1 = scwin.fn_getPreYear(1);
        sCURTRM_1 = scwin.fn_getCurYear(1);
    }
    scwin.arrPar[0] = {
        QTR_1: sQTR_1,
        QTR_2: sQTR_2,
        QTR_3: sQTR_3,
        FSTTRM: sFSTTRM,
        CURTRM: sCURTRM,
        FSTTRM_1: sFSTTRM_1,
        CURTRM_1: sCURTRM_1,
        FSTTRM_2: sFSTTRM_2,
        CURTRM_2: sCURTRM_2,
        FSTTRM_3: sFSTTRM_3,
        CURTRM_3: sCURTRM_3
    };
};
scwin.fn_getWrtrptKindCd = function() {
    var str = "";
    if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '3') {
        str = '1분기';
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '5') {
        str = '상반기';
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '6') {
        str = '3분기';
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '1') {
        str = '';
    }
    return str;
};
scwin.fn_getWrtrptKindTm = function() {
    var arrTm = new Array();
    var str_1 = "";
    var str_2 = "";
    if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '3') {
        str_1 = '1분기';
        str_2 = '';
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '5') {
        str_1 = '상반기(1~6월)';
        str_2 = '2분기(4~6월)';
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '6') {
        str_1 = '3분기 누적(1~9월)';
        str_2 = '3분기(7~9월)';
    } else if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '1') {
        str_1 = '';
        str_2 = '';
    }
    arrTm[0] = {
        QTR_TP_1: str_1,
        QTR_TP_2: str_2
    };
    return arrTm;
};
scwin.fn_getFsWrtMethdCd = function() {
    var str = "";
    if (MaxTab_01.getSelectedTabIndex() == 7) {
        //지배

    } else {
        if ($c.stf.getObjectValue(rdo_MKT_ID) == '1') {
            if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '1') {
                str = '(개별실적)';
            } else if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '2') {
                str = '(연결실적)';
            } else if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '3') {

            }
        } else if ($c.stf.getObjectValue(rdo_MKT_ID) == '2') {
            if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '1') {
                str = '';
            } else if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '2') {
                str = '(연결실적)';
            } else if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '3') {
                str = '(별도실적)';
            }
        }
    }
    return str;
};
scwin.fn_getUserParam = function(pTitle, psTitle) {
    var userParam;
    userParam = [{
        uid: "MKT_ID",
        unm: $c.stf.getObjectValue(rdo_MKT_ID)
    }, {
        uid: "FS_WRT_METHD_CD",
        unm: $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD)
    }, {
        uid: "WRTRPT_KIND_CD",
        unm: $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD)
    }, {
        uid: "PREF_CF",
        unm: "□  개별실적과 연결실적 비교(" + scwin.fn_getCurYear(1) + " " + scwin.fn_getWrtrptKindCd() + " 기준)"
    }, {
        uid: "TITLE",
        unm: pTitle + scwin.fn_getFsWrtMethdCd()
    }, {
        uid: "STITLE",
        unm: psTitle
    }, {
        uid: "QTR_1",
        unm: scwin.arrPar[0].QTR_1
    }, {
        uid: "QTR_2",
        unm: scwin.arrPar[0].QTR_2
    }, {
        uid: "QTR_3",
        unm: scwin.arrPar[0].QTR_3
    }, {
        uid: "FSTTRM",
        unm: scwin.arrPar[0].FSTTRM
    }, {
        uid: "CURTRM",
        unm: scwin.arrPar[0].CURTRM
    }, {
        uid: "FSTTRM_1",
        unm: scwin.arrPar[0].FSTTRM_1
    }, {
        uid: "CURTRM_1",
        unm: scwin.arrPar[0].CURTRM_1
    }, {
        uid: "FSTTRM_2",
        unm: scwin.arrPar[0].FSTTRM_2
    }, {
        uid: "CURTRM_2",
        unm: scwin.arrPar[0].CURTRM_2
    }, {
        uid: "FSTTRM_3",
        unm: scwin.arrPar[0].FSTTRM_3
    }, {
        uid: "CURTRM_3",
        unm: scwin.arrPar[0].CURTRM_3
    }];
    return userParam;
};
scwin.fn_totalPrint_K = function(dtsObj_1A, dtsObj_1B, dtsObj_1C, dtsObj_2A, dtsObj_2B, dtsObj_3A, dtsObj_3B, dtsObj_1D) {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Print.insertRow();
    var vTitle = "2. 12월 결산법인 " + scwin.fn_getCurYear(0) + "사업연도 " + scwin.fn_getWrtrptKindCd() + " 실적 및 재무현황 총괄표";
    var sTitle = "□ 자본 및 부채 구성";
    var rex_rptname = "RLDSTF00110_K";
    var userParam = scwin.fn_getUserParam(vTitle, sTitle);
    testDateSet = rex_gfGetGauceCsvStr(dts_Print, dtsObj_1A, dtsObj_1B, dtsObj_1C, dtsObj_2A, dtsObj_2B, dtsObj_3A, dtsObj_3B, dtsObj_1D);
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);
};


/**
 * 2018.03.29 다운로드 기능 개선
 * Rexpert Preview -> PDF
 */
scwin.fn_totalPrint_K_pdf = function(dtsObj_1A, dtsObj_1B, dtsObj_1C, dtsObj_2A, dtsObj_2B, dtsObj_3A, dtsObj_3B, dtsObj_1D) {
    var pdf_rptname = "RLDSTF00110_K";

    //재무제표구분_별도(3)
    if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '3') {
        pdf_rptname = "RLDSTF00110_K_2";
    }

    //보고서종류_반기(5),  3분기(6)
    if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '5' || $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '6') {
        pdf_rptname = "RLDSTF00110_K_3";

        //재무제표구분_별도(3)
        if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '3') {
            pdf_rptname = "RLDSTF00110_K_4";
        }
    }
    var vTitle = "2. 12월 결산법인 " + scwin.fn_getCurYear(0) + "사업연도 " + scwin.fn_getWrtrptKindCd() + " 실적 및 재무현황 총괄표";
    var sTitle = "□ 자본 및 부채 구성";
    var userParam = [{
        uid: "H_MKT_ID",
        unm: $c.stf.getObjectValue(rdo_MKT_ID)
    }, {
        uid: "H_FS_WRT_METHD_CD",
        unm: $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD)
    }, {
        uid: "H_WRTRPT_KIND_CD",
        unm: $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD)
    }, {
        uid: "H_PREF_CF",
        unm: "□  개별실적과 연결실적 비교(" + scwin.fn_getCurYear(1) + " " + scwin.fn_getWrtrptKindCd() + " 기준)"
    }, {
        uid: "H_TITLE",
        unm: vTitle + scwin.fn_getFsWrtMethdCd()
    }, {
        uid: "H_STITLE",
        unm: sTitle
    }, {
        uid: "H_QTR_1",
        unm: scwin.arrPar[0].QTR_1
    }, {
        uid: "H_QTR_2",
        unm: scwin.arrPar[0].QTR_2
    }, {
        uid: "H_QTR_3",
        unm: scwin.arrPar[0].QTR_3
    }, {
        uid: "H_FSTTRM",
        unm: scwin.arrPar[0].FSTTRM
    }, {
        uid: "H_CURTRM",
        unm: scwin.arrPar[0].CURTRM
    }, {
        uid: "H_FSTTRM_1",
        unm: scwin.arrPar[0].FSTTRM_1
    }, {
        uid: "H_CURTRM_1",
        unm: scwin.arrPar[0].CURTRM_1
