scwin.fn_SetCode = function() {
    scwin.gLdMktTp = js_market;
};
scwin.fn_Init = function() {
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    //var str = "^--선택해주세요,";
    var str2 = "";
    for (var i = yyyy; i >= 2008; i--) {
        //str += i + "^" + i + ",";
        str2 += i + "^" + i + ",";
    }
    //str = str.substring(0, str.length - 1);
    str2 = str2.substring(0, str2.length - 1);
    cmb_ACNTCLS_YY.CBData = str2;
};
