scwin.fn_gridInit = function() {
    var g_MKT_ID = $c.stf.getObjectValue(rdo_MKT_ID);
    var g_FS_WRT_METHD_CD = $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD);
    var isView = true;
    if (g_MKT_ID == '1') {
        isView = false;
        panel_2_1_P.style.top = "247px";
    } else if (g_MKT_ID == '2') {
        isView = true;
        panel_2_1_P.style.top = "463px";
