scwin.fn_list_sync = function() {
    if ($c.stf.getObjectValue(cmb_ACNTCLS_YY) == '') {
        $c.win.alert("결산년도를 선택해주세요.");
        return;
    }
    scwin.fn_gridInit();
    scwin.fn_panelInit();
    scwin.fn_gridNameChange();
    var searchYn = 'Y';
    if ($c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '3' || $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) == '1') {
        //3=1분기, 1=결산
        searchYn = 'N';
    }
    scwin.fn_dataSetDeleteAll(); //최기화

    if (MaxTab_01.getSelectedTabIndex() == 1) {
        scwin.fn_2sync(dts_2_1A, "A2_IS", scwin.V_DATA_CD_1, scwin.V_RANK_CD, scwin.V_ITEM_CD_B);
        scwin.fn_2sync(dts_2_1B, "A2_IS", scwin.V_DATA_CD_1, scwin.V_RANK_CD, scwin.V_ITEM_CD_A);
        scwin.fn_2sync(dts_2_1C, "A2_BS", scwin.V_DATA_CD_1, scwin.V_RANK_CD, scwin.V_ITEM_CD);
        if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == '3') {
            //FS_WRT_METHD_CD 3: 별도
            scwin.fn_2sync(dts_2_1D, "A2_CMP", scwin.V_DATA_CD, scwin.V_RANK_CD, scwin.V_ITEM_CD);
