scwin.fn_2sync = function(dtsObj, sSEARCH_TYP, sDATA_CD, sRANK_CD, sITEM_CD) {
    var url = "/FncPrfmNewsData.do?method=selectFncPrfmNewsDataMgt" + "&SEARCH_TYP=" + sSEARCH_TYP + "&ACNTCLS_YY=" + $c.stf.getObjectValue(cmb_ACNTCLS_YY) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_ACNTCLS_MM) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&WRTRPT_KIND_CD=" + $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) + "&FS_WRT_METHD_CD=" + $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) + "&RANK_UNIT=" + $c.stf.getObjectValue(cmb_RANK_UNIT) + "&DATA_CD=" + sDATA_CD + "&ITEM_CD=" + sITEM_CD + "&RANK_CD=" + sRANK_CD + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
};
