 */
scwin.array_type_01 = function(obj) {
    var array = new Array();
    for (var i = 1; i <= obj.getTotalRow(); i++) {
        array[i - 1] = {
            ISUR_CD: obj.getCellData(i, "ISUR_CD"),
            COM_ABBRV: obj.getCellData(i, "COM_ABBRV"),
            FSTTRM: scwin.minusCheck(obj.getCellData(i, "FSTTRM")),
            CURTRM: scwin.minusCheck(obj.getCellData(i, "CURTRM")),
            INCDEC_AMT: scwin.minusCheck(obj.getCellData(i, "INCDEC_AMT")),
            INCDEC_RT: scwin.minusCheck(obj.getCellData(i, "INCDEC_RT")),
            FNC_ACNT_NM: obj.getCellData(i, "FNC_ACNT_NM"),
            SECT_TP_NM: obj.getCellData(i, "SECT_TP_NM"),
            ISUR_NUM: obj.getCellData(i, "ISUR_NUM")
        };
    }
    return {
        arrayData: array
    };
};
