/**
 * DATASET -> HTML 처리
 * 01 : 합계(all), 개별(each)
 */
scwin.html_type_01 = function(obj, type) {
    var html = "<tbody>";
    var target_sect_tp_nm = "";
    for (var i = 1; i <= obj.getTotalRow(); i++) {
        html = html + "<tr>";
        if (type == "all" && target_sect_tp_nm == "") {
            target_sect_tp_nm = "합계";
            html = html + "<td class=\"alignC\" width=\"10%\" rowspan=\"" + obj.getTotalRow() + "\">" + target_sect_tp_nm + "<br />(" + obj.getCellData(i, "ISUR_NUM") + " 사)</td>";
        } else if (type == "each" && target_sect_tp_nm != obj.getCellData(i, "SECT_TP_NM")) {
            target_sect_tp_nm = obj.getCellData(i, "SECT_TP_NM");
            html = html + "<td class=\"alignC\" width=\"10%\" rowspan=\"" + scwin.html_type_01_ron_count(obj, obj.getCellData(i, "SECT_TP_NM")) + "\">" + obj.getCellData(i, "SECT_TP_NM") + "<br />(" + obj.getCellData(i, "ISUR_NUM") + " 사)</td>";
        }
        html = html + "<td class=\"alignL\" width=\"22%\">" + obj.getCellData(i, "FNC_ACNT_NM") + "</td>";
        html = html + "<td class=\"alignR\">" + scwin.minusCheck(obj.getCellData(i, "FSTTRM")) + "</td>";
        html = html + "<td class=\"alignR\">" + scwin.minusCheck(obj.getCellData(i, "CURTRM")) + "</td>";
        html = html + "<td class=\"alignR\">" + scwin.minusCheck(obj.getCellData(i, "INCDEC_AMT")) + "</td>";
        html = html + "<td class=\"alignR\">" + scwin.minusCheck(obj.getCellData(i, "INCDEC_RT")) + "</td>";
        html = html + "</tr>";
    }
    html = html + "</tbody>";
    return html;
};
scwin.html_type_01_ron_count = function(obj, target_sect_tp_nm) {
    var count = 0;
    for (var i = 1; i <= obj.getTotalRow(); i++) {
        if (obj.getCellData(i, "SECT_TP_NM") == target_sect_tp_nm) {
            count++;
        }
    }
    return count;
};
scwin.minusCheck = function(data) {
    if (data.indexOf("-") != -1) {
        data = "<font color=\"red\">" + data + "</font>";
    }
    return data;
};
